use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_ids = input.as_array().unwrap().iter().map(|&(priority, id)| (id, priority)).collect();
    sorted_ids.sort_by(|a, b| b.1.cmp(&a.1));
    sorted_ids.into_iter().map(|(_, id)| id).collect()
}

fn main() {
    let input = serde_json::Value::from("[[2,7],[3,8],[2,1]]");
    let expected = serde_json::Value::from(vec![8, 1, 7]);
    assert_eq!(solve(input), expected);
}
